+++ b/src/service.ts
@@ -1,8 +1,35 @@
 import type { ZoneRules } from "./zone.ts";
+import { ZoneError, parseZone } from "./zone.ts";

 export const ZONES_URL = "https://tzdata.ops.internal/v1/zones";

+const ZONE_NAME_RE = /^[A-Za-z_]+\/[A-Za-z0-9_+-]+(?:\/[A-Za-z0-9_+-]+)*$/;
+
 /** Load the rules of a zone from the tz service. */
 export async function fetchZone(name: string): Promise<ZoneRules> {
-  throw new Error("not implemented");
+  if (!ZONE_NAME_RE.test(name)) {
+    throw new RangeError("invalid zone name");
+  }
+
+  let response: Response;
+  try {
+    const encodedName = name.split("/").map(encodeURIComponent).join("/");
+    response = await fetch(`${ZONES_URL}/${encodedName}`);
+  } catch (error) {
+    const message = error instanceof Error ? error.message : String(error);
+    throw new ZoneError(`tz service unavailable: ${message}`);
+  }
+
+  if (!response.ok) {
+    throw new ZoneError(`tz service unavailable: HTTP ${response.status}`);
+  }
+
+  let body: unknown;
+  try {
+    body = await response.json();
+  } catch {
+    throw new ZoneError("invalid JSON from tz service");
+  }
+
+  return parseZone(body);
 }
